<div class="page-actions"><div><p class="muted">Posisi stok per produk dan gudang.</p></div><a class="btn btn-primary" href="?page=movements">Lihat Stock Movement</a></div>
<div class="card filter-card"><form class="filter-grid stock-filter-grid" method="get"><input type="hidden" name="page" value="stock"><input aria-label="Cari stok produk atau gudang" name="search" value="<?=e($filters['search'])?>" placeholder="Cari produk / gudang..."><select aria-label="Filter gudang" name="warehouse_id"><option value="">Semua gudang</option><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>" <?=$filters['warehouse_id']==$w['id']?'selected':''?>><?=e($w['name'])?></option><?php endforeach;?></select><select aria-label="Filter ketersediaan stok" name="stock_status"><option value="available" <?=$filters['stock_status']==='available'?'selected':''?>>Stok tersedia</option><option value="zero" <?=$filters['stock_status']==='zero'?'selected':''?>>Stok 0</option><option value="all" <?=$filters['stock_status']==='all'?'selected':''?>>Semua stok</option></select><button class="btn btn-primary">Filter</button><a class="btn" href="?page=stock">Reset</a></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Produk</th><th>Gudang</th><th>Stok Masuk</th><th>Stok Keluar</th><th>Stok Saat Ini</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php foreach($result['items'] as $r):$low=(float)$r['current_stock']<=(float)$r['minimum_stock'];?><tr><td><?=e($r['product_code'])?></td><td><a class="link" href="?page=stock&amp;action=view&amp;id=<?=(int)$r['product_id']?>"><?=e($r['product_name'])?></a></td><td><?=e($r['warehouse_name'])?></td><td><?=number_format((float)$r['stock_in'],2,',','.')?> <?=e($r['unit'])?></td><td><?=number_format((float)$r['stock_out'],2,',','.')?> <?=e($r['unit'])?></td><td><strong><?=$low?'<span class="badge priority-high">':''?><?=number_format((float)$r['current_stock'],2,',','.')?> <?=$low?'</span>':''?></strong></td><td><?=number_format((float)$r['minimum_stock'],2,',','.')?></td><td><?=$low?'<span class="badge priority-high">Stok Rendah</span>':'<span class="badge status-active">Aman</span>'?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="8" class="empty">Tidak ada stok untuk filter ini.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($result,['page'=>'stock','search'=>$filters['search'],'warehouse_id'=>$filters['warehouse_id'],'stock_status'=>$filters['stock_status']])?></div>
